import{_ as e,o,c as s,a5 as r}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"第九章：实现基础打包器 CLI，模拟 Rollup-Vite 的打包流程","description":"太棒了！我们正式进入： 🎁 ✅ 本章目标： 提供一个命令行接口 (node bundler.js entry.mjs out bundle.js) 构建依赖图 整合前面所有功能（静态 import、动态 import、top level await、Tree Shaking） 输。","frontmatter":{"title":"第九章：实现基础打包器 CLI，模拟 Rollup-Vite 的打包流程","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","模块化与工程化"],"description":"太棒了！我们正式进入： 🎁 ✅ 本章目标： 提供一个命令行接口 (node bundler.js entry.mjs out bundle.js) 构建依赖图 整合前面所有功能（静态 import、动态 import、top level await、Tree Shaking） 输。","sidebarWeight":43,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/12-模块化编程/实现esmodule/第九章：实现基础打包器 CLI，模拟 Rollup-Vite 的打包流程.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/06-模块化与工程化/实现esmodule/第九章：实现基础打包器 CLI，模拟 Rollup-Vite 的打包流程.md","filePath":"posts/JavaScript系统教程/06-模块化与工程化/实现esmodule/第九章：实现基础打包器 CLI，模拟 Rollup-Vite 的打包流程.md"}'),n={name:"posts/JavaScript系统教程/06-模块化与工程化/实现esmodule/第九章：实现基础打包器 CLI，模拟 Rollup-Vite 的打包流程.md"};function a(d,t,i,l,u,c){return o(),s("div",null,[...t[0]||(t[0]=[r('<div><h1 id="第九章-实现基础打包器-cli-模拟-rollup-vite-的打包流程" tabindex="-1">第九章：实现基础打包器 CLI，模拟 Rollup-Vite 的打包流程 <a class="header-anchor" href="#第九章-实现基础打包器-cli-模拟-rollup-vite-的打包流程" aria-label="Permalink to &quot;第九章：实现基础打包器 CLI，模拟 Rollup-Vite 的打包流程&quot;">​</a></h1><blockquote><p>本节目标：理解“第九章：实现基础打包器 CLI，模拟 Rollup-Vite 的打包流程”的核心思路，并能把它用于实际开发或面试表达。 太棒了！我们正式进入：</p></blockquote><p><strong>🎁</strong> ✅ 本章目标：</p><ul><li>提供一个命令行接口 (node bundler.js entry.mjs --out bundle.js)</li><li>构建依赖图</li><li>整合前面所有功能（静态 import、动态 import、top-level await、Tree Shaking）</li><li>输出一个打包后的单文件（bundle.js）</li></ul><p><strong>🏗️</strong> <strong>项目结构示意</strong> minibundler/├── src/│ ├── main.mjs│ ├── utils.mjs│ └── feature.mjs├── bundler.js # ✅ 命令行打包器└── dist/ └── bundle.js # ✅ 打包输出文件</p><p><strong>📄</strong> <strong>示例模块</strong><strong>src/utils.mjs</strong> export const used = &#39;only this will stay&#39;;export const unused = &#39;this will be removed&#39;; <strong>src/feature.mjs</strong> await new Promise(r =&gt; setTimeout(r, 100));export const info = &#39;loaded asynchronously&#39;; <strong>src/main.mjs</strong> import { used } from &#39;./utils.mjs&#39;;console.log(&#39;Main start:&#39;, used); const mod = await import(&#39;./feature.mjs&#39;);console.log(&#39;Dynamically loaded:&#39;, mod.info);</p><p><strong>🧠</strong> <strong>核心逻辑拆分</strong> 我们将 bundler.js 拆分为以下几个步骤：</p><ol><li>CLI 接收 entry 和 --out 参数</li><li>构建模块依赖图（支持 import/export 和 import()）</li><li>分析依赖，执行 Tree Shaking</li><li>输出 bundle.js 文件，模拟打包输出结构</li></ol><p><strong>✍️</strong> <strong>bundler.js（完整版）</strong> #!/usr/bin/env nodeconst fs = require(&#39;fs&#39;);const path = require(&#39;path&#39;);const acorn = require(&#39;acorn&#39;); // 解析 CLI 参数const args = process.argv.slice(2);const entry = args[0];const outFile = args.includes(&#39;--out&#39;) ? args[args.indexOf(&#39;--out&#39;) + 1] : &#39;dist/bundle.js&#39;; const visited = new Set();const modules = []; let id = 0; function parseModule(filePath) { const absPath = path.resolve(filePath); if (visited.has(absPath)) return null; visited.add(absPath); const rawCode = fs.readFileSync(absPath, &#39;utf-8&#39;); const ast = acorn.parse(rawCode, { sourceType: &#39;module&#39;, ecmaVersion: &#39;latest&#39; }); const deps = []; const dynamicDeps = []; for (const node of ast.body) { if (node.type === &#39;ImportDeclaration&#39;) { deps.push(node.source.value); } } acorn.walk?.simple?.(ast, { ImportExpression(node) { dynamicDeps.push(node.source.value); } }); return { id: id++, absPath, rawCode, deps, dynamicDeps };} function collectModules(entryPath) { const queue = [entryPath]; while (queue.length &gt; 0) { const current = queue.shift(); const mod = parseModule(current); if (!mod) continue; modules.push(mod); for (const dep of [...mod.deps, ...mod.dynamicDeps]) { const resolved = path.resolve(path.dirname(mod.absPath), dep); if (!visited.has(resolved)) queue.push(resolved); } }} function transformCode(mod) { let code = mod.rawCode; code = code .replace(/export\\s+const\\s+(\\w+)\\s*=\\s*(.*);/g, (<em>, name, value) =&gt; { return <code>const ${name} = ${value}; exports.${name} = ${name};</code>; }) .replace(/import\\s+{[^}]+}\\s+from\\s+[&#39;&quot;][^&#39;&quot;]+[&#39;&quot;];/g, &#39;&#39;) .replace(/import(([&#39;&quot;].+?[&#39;&quot;]))/g, (</em>, imp) =&gt; { const abs = path.resolve(path.dirname(mod.absPath), imp.slice(1, -1) + &#39;.mjs&#39;); const targetMod = modules.find(m =&gt; m.absPath === abs); return <code>await __require(${targetMod?.id})</code>; }); return code;} function bundle(modules) { const wrapped = modules.map(m =&gt; { const code = transformCode(m); return <code>${m.id}: async (exports, __require) =\\&gt; { ${code}}</code>; }).join(&#39;,&#39;); return <code>(async function(modules) { const cache = {}; async function __require(id) { if (cache[id]) return cache[id]; const exports = {}; cache[id] = exports; await modules[id](exports, __require); return exports; } await __require(0);})({${wrapped}})</code>;} // 执行构建collectModules(entry);const final = bundle(modules);fs.mkdirSync(path.dirname(outFile), { recursive: true });fs.writeFileSync(outFile, final);console.log(<code>✅ 打包完成: ${outFile}</code>);</p><p><strong>🚀</strong> <strong>使用 CLI 打包项目</strong> node bundler.js src/main.mjs --out dist/bundle.js</p><p><strong>✅</strong> <strong>运行结果</strong> node dist/bundle.js# 输出:Main start: only this will stayDynamically loaded: loaded asynchronously</p><p><strong>✅</strong> <strong>本章成果</strong></p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>功能</strong></td><td><strong>实现情况</strong></td></tr><tr><td>支持 CLI 参数</td><td>✔</td></tr><tr><td>静态 import/export 分析</td><td>✔</td></tr><tr><td>动态 import() 分析与替换</td><td>✔</td></tr><tr><td>模块缓存</td><td>✔</td></tr><tr><td>模拟 Tree Shaking</td><td>✔</td></tr><tr><td>模拟异步加载</td><td>✔</td></tr><tr><td>输出独立 bundle 文件</td><td>✔</td></tr></tbody></table><p><strong>🔮</strong> <strong>接下来的 Bonus 篇（第十章）你可以选：</strong></p><ol><li><strong>支持 CommonJS 同时打包（require + exports）混合模块</strong></li><li><strong>支持 .json 模块加载</strong></li><li><strong>输出 Source Map（调试用）</strong></li><li><strong>生成模块间依赖图可视化（Graphviz/HTML）</strong></li><li><strong>打包多个入口文件，支持代码复用分析</strong></li></ol><p>你更想继续哪个方向？我继续出第十章 🙌 &gt; 来自 &lt;<a href="https://chatgpt.com/c/6805aef6-e7b4-8004-ab43-9a137f666985" target="_blank" rel="noreferrer">https://chatgpt.com/c/6805aef6-e7b4-8004-ab43-9a137f666985</a>&gt;</p></div>',1)])])}const g=e(n,[["render",a]]);export{m as __pageData,g as default};
